import {seaSector} from './presence-core.js?v=2026.11.10-performance-map';
import {openOfflineRaid,advanceOfflineRaid} from './defense-core.js?v=2026.11.10-performance-map';
import {readDefense,refreshDefense,publishDefense} from './defense-account.js?v=2026.11.10-performance-map';
import {cannonStats} from './cannons.js?v=2026.11.10-performance-map';
import {mapDistance} from './world-wrap.js?v=2026.11.10-performance-map';
const roll=()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296;
export function createOfflineCombat(api){
 const a=api.account;let room=null,id=null,roomOff=null,connectionOff=null,ownOff=null,connection=null,working=false,lastAuto=0,lastError=0;
 const now=()=>Date.now()+(a.serverOffset||0),ref=p=>a.sdk.ref(a.db,'gameV2/'+p),read=async p=>(await a.sdk.get(ref(p))).val();
 function changes(r){const out={};for(const [uid,n,changed]of [[r.room.a,r.actorNode,r.changedActor],[r.room.b,r.node,r.changedTarget]]){if(!changed)continue;out['fleetStates/'+uid]={...n,at:a.sdk.serverTimestamp()};out['combatSlots/'+uid]=r.room.status==='active'?'raid:'+r.room.id:null;if(n.rescuePending){out['real/fleetIndex/'+seaSector(n.point)+'/'+uid]=null;out['combatVaults/'+uid]=null;}}return out;}
 const offline=c=>!c||c.online===false||now()-c.at>45000;
 function watch(key){if(id===key&&roomOff)return;roomOff?.();connectionOff?.();id=key;room=null;if(!key){api.render();return;}
  roomOff=a.sdk.onValue(ref('shared/raids/'+key),snapshot=>{room=snapshot.val()?.content||null;if(!room)return;api.pause();api.close();const other=room.a===a.uid?room.b:room.a;api.focus?.(room.players[other].point);for(const event of room.events||[]){if(now()-event.at>5000)continue;const target=event.actor===room.a?room.b:room.a,from=room.players[event.actor].point,to=room.players[target].point;if(mapDistance(api.getState().position,from)<=180&&mapDistance(api.getState().position,to)<=180)api.effects.shot('raid:'+key+':'+event.sequence,from,to,event);}api.render();});
  read('shared/raids/'+key).then(row=>{if(id!==key||!row)return;const target=row.content.a===a.uid?row.content.b:row.content.a;connectionOff=a.sdk.onValue(ref('real/fleetConnections/'+target),snap=>connection=snap.val());}).catch(()=>{});
 }
 async function connect(){if(!a.defenseEnabled)return;dispose();ownOff=a.sdk.onValue(ref('fleetStates/'+a.uid),snap=>{const n=snap.val();if(!n)return;if(n.seq>(api.getState().defenseAck?.seq||0)){api.pause();a.enqueue(()=>refreshDefense(a)).then(()=>{api.changed();if(api.getState().offlineRescuePending)api.rescue();if(n.activeRaidId&&n.raidUntil>now())watch(n.activeRaidId);}).catch(e=>api.toast(e.message));}});if(api.getState().raidId)watch(api.getState().raidId);}
 async function start(uid){if(working)return;api.pause();await api.prepare();await api.syncPosition?.();await publishDefense(a);const target=await readDefense(a,uid),c=await read('real/fleetConnections/'+uid);if(!target||!offline(c))throw Error('상대가 접속했어요. 최신 선장 전투에서 다시 선택하세요.');const key=crypto.randomUUID();const gun=(api.getState().cannons||[]).find(g=>g.shipId&&g.readyAt<=now());if(!gun)throw Error('발사 가능한 장착 대포가 필요해요.');
  await api.commit('raids',key,async(game,content,time)=>{const latest=await readDefense(a,uid),conn=await read('real/fleetConnections/'+uid);if(!offline(conn))throw Error('상대가 접속했어요.');const opened=openOfflineRaid(game,latest,{uid:a.uid,name:a.name},{uid,session:conn?.session||latest.session},key,time,api.nav().clear.bind(api.nav()));Object.assign(content,opened.room);const actor=await readDefense(a,a.uid);const r=advanceOfflineRaid(game,content,opened.node,a.uid,{kind:'fire',gunId:gun.id,autoDefense:true},time,[roll(),roll()],api.nav().clear.bind(api.nav()),actor);return {...r,extras:changes(r)};});watch(key);api.close();api.pause();api.focus?.(target.point);
 }
 async function act(action){if(working||!room)return;working=true;try{const key=id;await api.commit('raids',key,async(game,content,time)=>{const actor=await readDefense(a,content.a),node=await readDefense(a,content.defender),conn=await read('real/fleetConnections/'+(content.a===a.uid?content.b:content.a));if(action.kind==='auto'&&!offline(conn))throw Error('방어 선장이 접속하여 직접 조종합니다.');const r=advanceOfflineRaid(game,content,node,a.uid,{...action,autoDefense:offline(conn)},time,[roll(),roll()],api.nav().clear.bind(api.nav()),actor);return {...r,extras:changes(r)};});if(api.getState().offlineRescuePending)api.rescue();}finally{working=false;api.render();}}
 async function tick(){if(!room||working||!a.ready||a.busy||now()-lastAuto<500)return;if(room.status!=='active')return;if(now()>=room.deadline){lastAuto=now();await act({kind:'draw'}).catch(report);return;}const other=room.a===a.uid?room.b:room.a;if(offline(connection)&&room.players[other].wasAttacked&&room.players[other].guns?.some(g=>g.readyAt<=now())){lastAuto=now();await act({kind:'auto'}).catch(report);}}
 function report(e){if(now()-lastError>10000){lastError=now();api.toast(e.message);}}
 function model(){if(!room)return null;const other=room.a===a.uid?room.b:room.a,me=room.players[a.uid],enemy=room.players[other],inRange=mapDistance(api.getState().position,enemy.point)<=180;return {key:'raid:'+id,title:(room.status==='draw'?'교전 종료 · ':'해상 전투 · ')+enemy.name+(offline(connection)?' (오프라인)':''),me:{...me,point:api.getState().position},enemy:{...enemy,point:inRange?enemy.point:null},guns:(me.guns||[]).map(g=>({...g,name:cannonStats(g).name})),busy:working,inRange,closed:room.status!=='active',canRetreat:room.status==='active',message:room.status==='active'?(room.events?.at(-1)?.text||'교전 중')+' · 남은 '+Math.max(0,Math.ceil((room.deadline-now())/1000))+'초':room.reason,actions:room.status==='active'?[]:[['항해 계속하기',()=>{watch(null);api.render();}]]};}
 function dispose(){roomOff?.();connectionOff?.();ownOff?.();roomOff=connectionOff=ownOff=null;room=null;id=null;}
 return {connect,start,watch,fire:gunId=>act({kind:'fire',gunId}),retreat:()=>act({kind:'retreat'}),tick,model,dispose,hasRoom:()=>!!room,active:()=>room?.status==='active',blocked:()=>room?.status==='active'||!!api.getState().raidId};
}
